mapper.select:
/* file : DTModelMapper.xml, id : getDTEtcModelList */ SELECT * FROM ( SELECT A.* , (SELECT DTL_CD_NM FROM TB_CODE_DTL T WHERE T.DEL_YN = 'N' AND T.GRP_CD = 'STATUS' AND T.DTL_CD = A.MODEL_STATUS) STATUS_NM , (SELECT DTL_CD_NM FROM TB_CODE_DTL T WHERE T.DEL_YN = 'N' AND T.GRP_CD = 'ETC_MODEL_TYPE' AND T.DTL_CD = A.ETC_MODEL_TP) ETC_MODEL_TP_NM , (SELECT USER_ID FROM TB_USER U WHERE U.DEL_YN = 'N' AND U.USER_SEQ = A.REG_USER_SEQ) USER_ID FROM TB_META_ETC_MODEL A WHERE A.DEL_YN = 'N' AND A.USE_YN = 'Y' ) TB WHERE ETC_MODEL_TP = #{model_tp}
AND ETC_MODEL_NM LIKE CONCAT('%', #{keyword}, '%')
ORDER BY REG_DT DESC /*||ORDER BY REG_DT DESC||*/

/* file : DTModelMapper.xml, id : getDTModelListSetUserSeq */ SELECT * FROM ( SELECT A.* , (SELECT DTL_CD_NM FROM TB_CODE_DTL T WHERE T.DEL_YN = 'N' AND T.GRP_CD = 'STATUS' AND T.DTL_CD = A.MODEL_STATUS) STATUS_NM , (SELECT DTL_CD_NM FROM TB_CODE_DTL T WHERE T.DEL_YN = 'N' AND T.GRP_CD = 'ETC_MODEL_TYPE' AND T.DTL_CD = A.ETC_MODEL_TP) ETC_MODEL_TP_NM , (SELECT USER_ID FROM TB_USER U WHERE U.DEL_YN = 'N' AND U.USER_SEQ = A.REG_USER_SEQ) USER_ID FROM TB_META_ETC_MODEL A WHERE A.DEL_YN = 'N' AND A.USE_YN = 'Y' AND A.REG_USER_SEQ = #{user_seq} ) TB WHERE ETC_MODEL_TP = #{model_tp}
AND ETC_MODEL_NM LIKE CONCAT('%', #{keyword}, '%')
ORDER BY REG_DT ASC

/* file : DTModelMapper.xml, id : getDTModelSharedList */ SELECT * FROM ( SELECT A.* , (SELECT DTL_CD_NM FROM TB_CODE_DTL T WHERE T.DEL_YN = 'N' AND T.GRP_CD = 'STATUS' AND T.DTL_CD = A.MODEL_STATUS) STATUS_NM , (SELECT DTL_CD_NM FROM TB_CODE_DTL T WHERE T.DEL_YN = 'N' AND T.GRP_CD = 'ETC_MODEL_TYPE' AND T.DTL_CD = A.ETC_MODEL_TP) ETC_MODEL_TP_NM , (SELECT USER_ID FROM TB_USER U WHERE U.DEL_YN = 'N' AND U.USER_SEQ = A.REG_USER_SEQ) USER_ID FROM TB_META_ETC_MODEL A WHERE A.DEL_YN = 'N' AND A.USE_YN = 'Y' AND A.RLS_YN = 'Y' AND A.MODEL_STATUS = 'DONE' ) TB
WHERE ETC_MODEL_NM LIKE CONCAT('%', #{sub_keyword}, '%')
/*||ORDER BY REG_DT DESC||*/

/* file : DTModelMapper.xml, id : getDTModelSharedList */ SELECT * FROM ( SELECT A.* , (SELECT DTL_CD_NM FROM TB_CODE_DTL T WHERE T.DEL_YN = 'N' AND T.GRP_CD = 'STATUS' AND T.DTL_CD = A.MODEL_STATUS) STATUS_NM , (SELECT DTL_CD_NM FROM TB_CODE_DTL T WHERE T.DEL_YN = 'N' AND T.GRP_CD = 'ETC_MODEL_TYPE' AND T.DTL_CD = A.ETC_MODEL_TP) ETC_MODEL_TP_NM , (SELECT USER_ID FROM TB_USER U WHERE U.DEL_YN = 'N' AND U.USER_SEQ = A.REG_USER_SEQ) USER_ID FROM TB_META_ETC_MODEL A WHERE A.DEL_YN = 'N' AND A.USE_YN = 'Y' AND A.RLS_YN = 'Y' AND A.MODEL_STATUS = 'DONE' ) TB WHERE ETC_MODEL_TP = #{model_tp}
AND ETC_MODEL_NM LIKE CONCAT('%', #{sub_keyword}, '%')
/*||ORDER BY REG_DT DESC||*/

mapper.insert:
/* file : DTModelMapper.xml, id : insertDTModelEtc */
INSERT
INTO TB_META_ETC_MODEL (
ETC_MODEL_SEQ
, ETC_MODEL_NM
, ETC_MODEL_DERPN
, RLS_YN
, REG_USER_SEQ
, DATA_USE_TP
, MODEL_STATUS
, ETC_MODEL_TP
)
VALUES (
#{etcModelSeq}
, #{etcModelNm}
, #{etcModelDerpn}
, #{rlsYn}
, #{loginUserSeq}
, #{dataUseTp}
, #{modelStatus}
, #{etcModelTp}
)

    SELECT LAST_INSERT_ID()

/* file : DTModelMapper.xml, id : insertDTModelMetaUserItem */
INSERT
INTO TB_META_ETC_USER_ITEM (
USER_META_ITEM_SEQ
, ETC_MODEL_SEQ
, ORIGIN_META_ITEM_SEQ
, ORDBY
, INDEX_CRTR_YN
, USER_PPRCS_FULL_STNG_VALUE
, SDT_ID
, SDT_OBJ_ID
)
VALUES (
#{userMetaItemSeq}
, #{etcModelSeq}
, #{originMetaItemSeq}
, #{ordby}
, #{indexCrtrYn}
, #{userPprcsFullStngValue}
, #{twinId}
, #{twinObjId}
)

    SELECT LAST_INSERT_ID()

mapper.select:
/* file : AugmentModelMapper.xml, id : getAugmentModel */
SELECT *, (SELECT FILE_PATH FROM TB_META_ETC_MODEL_FILES WHERE ETC_MODEL_SEQ = #{modelSeq} LIMIT 1) FILE_PATH
FROM TB_META_ETC_MODEL A
WHERE A.DEL_YN = 'N'
  AND A.USE_YN = 'Y'
  AND A.ETC_MODEL_SEQ = #{modelSeq}

/* file : DTModelMapper.xml, id : selectMetaModel */
SELECT *
FROM TB_META_ETC_MODEL
WHERE ETC_MODEL_SEQ = #{modelSeq}

/* file : DTModelMapper.xml, id : selectMetaUserItem */
SELECT *
FROM TB_META_ETC_USER_ITEM
WHERE ETC_MODEL_SEQ = #{modelSeq}

mapper.delete:
/* file : MatchingMapper.xml, id : deleteAlgorithmModelParams */
DELETE
FROM TB_META_ETC_MODEL_PARAMS
WHERE ETC_MODEL_SEQ = #{etcModelSeq}

mapper.insert:
/* file : DTModelMapper.xml, id : saveAlgorithmModelParams */
INSERT
INTO TB_META_ETC_MODEL_PARAMS ( MODEL_PARAMS_SEQ
                              , ETC_MODEL_SEQ
                              , MODEL_ALGRM_SEQ
                              , MODEL_PARAMS_ITEM_SEQ
                              , MODEL_PARAMS_ITEM_VALUE)
VALUES ( #{modelParamsSeq}
       , #{etcModelSeq}
       , #{modelAlgrmSeq}
       , #{modelParamsItemSeq}
       , #{modelParamsItemValue})

mapper.update:
/* file : DTModelMapper.xml, id : updateAlgorithmSeq */
UPDATE TB_META_ETC_MODEL
SET MODEL_ALGRM_SEQ = #{algorithm_seq}
  , ETC_MODEL_TP=#{algorithm}
  , TRGT_COL        = #{trgt_col}
  , MDFCN_USER_SEQ  = #{reg_user_seq}
  , MDFCN_DT        = CURRENT_TIMESTAMP
  , MDFCN_IP        = #{reg_ip}
  , MODEL_STATUS    = 'WAIT'
WHERE ETC_MODEL_SEQ = #{etc_model_seq}

/* file : DTModelMapper.xml, id : updateMetaUerItemFulltext */
UPDATE TB_META_ETC_USER_ITEM
SET USER_PPRCS_FULL_STNG_VALUE = #{user_pprcs_full_stng_value}
WHERE ETC_MODEL_SEQ = #{model_seq}

mapper.insert:
