INSERT
INTO TB_META_ETC_MODEL_COLUMN ( ETC_MODEL_COL_SEQ
                              , ETC_MODEL_SEQ
                              , MODEL_COL_TP
                              , MODEL_COL_NM)
VALUES ( #{etcModelColSeq}
       , #{etcModelSeq}
       , #{modelColTp}
       , #{modelColNm})

